import http from 'http';
import fs from 'fs';
import path from 'path';
import type { AddressInfo } from 'net';
import chokidar, { FSWatcher } from 'chokidar';
import { WebSocket, WebSocketServer } from 'ws';
import { buildSite } from './generator';

export interface DevServerOptions {
  contentDir: string;
  outputDir: string;
  templateDir?: string;
  port?: number;
}

export const RELOAD_PATH = '/__ssg_live_reload';
const LIVE_RELOAD_SCRIPT_ID = 'ssg-live-reload';
const DEFAULT_REBUILD_DELAY_MS = 50;

const MIME_TYPES: Record<string, string> = {
  '.html': 'text/html; charset=utf-8',
  '.htm': 'text/html; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.mjs': 'text/javascript; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.gif': 'image/gif',
  '.webp': 'image/webp',
  '.svg': 'image/svg+xml',
  '.ico': 'image/x-icon',
  '.woff': 'font/woff',
  '.woff2': 'font/woff2',
  '.ttf': 'font/ttf',
  '.otf': 'font/otf',
  '.map': 'application/json; charset=utf-8',
  '.txt': 'text/plain; charset=utf-8',
  '.xml': 'application/xml; charset=utf-8',
};

/**
 * Build the client-side script that connects to the dev server's WebSocket
 * and reloads the page when a `reload` message arrives.
 */
export function liveReloadScript(wsUrl: string): string {
  const safeUrl = JSON.stringify(wsUrl);
  return [
    `<script id="${LIVE_RELOAD_SCRIPT_ID}">`,
    '(function () {',
    '  function connect() {',
    '    var ws = new WebSocket(' + safeUrl + ');',
    '    ws.addEventListener("message", function (event) {',
    '      var data = event.data;',
    '      if (typeof data === "string") {',
    '        try {',
    '          var parsed = JSON.parse(data);',
    '          if (parsed && parsed.type === "reload") {',
    '            window.location.reload();',
    '            return;',
    '          }',
    '        } catch (e) { /* not json */ }',
    '        if (data === "reload") {',
    '          window.location.reload();',
    '        }',
    '      }',
    '    });',
    '    ws.addEventListener("close", function () {',
    '      setTimeout(connect, 1000);',
    '    });',
    '  }',
    '  connect();',
    '})();',
    '</script>',
  ].join('\n');
}

/**
 * Inject the live reload script into an HTML document, right before the
 * closing `</body>` tag. Pages that already contain the script are returned
 * untouched.
 */
export function injectLiveReload(html: string, wsUrl: string): string {
  if (html.indexOf(LIVE_RELOAD_SCRIPT_ID) !== -1) {
    return html;
  }
  const script = liveReloadScript(wsUrl);
  const bodyEnd = html.lastIndexOf('</body>');
  if (bodyEnd === -1) {
    return `${html}\n${script}\n`;
  }
  return `${html.slice(0, bodyEnd)}\n${script}\n${html.slice(bodyEnd)}`;
}

export function buildWsUrl(hostHeader: string | undefined): string {
  const host = hostHeader || 'localhost';
  return `ws://${host}${RELOAD_PATH}`;
}

export interface DevServer {
  server: http.Server;
  wss: WebSocketServer;
  watcher: FSWatcher;
  port: number;
  reload(): void;
  rebuild(): void;
  close(): Promise<void>;
}

/**
 * Live-reload development server for the static site generator.
 *
 * Watches the content and template directories, rebuilds the site into the
 * output directory whenever a watched file changes, and notifies connected
 * browsers over WebSocket so they reload automatically. Static files are
 * served from the output directory with the live reload script injected into
 * HTML pages.
 */
export class LiveReloadDevServer implements DevServer {
  readonly server: http.Server;
  readonly wss: WebSocketServer;
  readonly watcher: FSWatcher;
  port: number;

  private readonly options: DevServerOptions;
  private readonly clients = new Set<WebSocket>();
  private rebuildTimer: NodeJS.Timeout | null = null;

  constructor(options: DevServerOptions) {
    this.options = options;
    this.port = options.port || 3000;

    this.server = http.createServer((req, res) => this.handleRequest(req, res));
    this.wss = new WebSocketServer({ server: this.server, path: RELOAD_PATH });
    this.wss.on('connection', (ws: WebSocket) => {
      this.clients.add(ws);
      ws.on('close', () => {
        this.clients.delete(ws);
      });
    });

    this.watcher = chokidar.watch(this.watchTargets(), {
      ignoreInitial: true,
    });
    this.watcher.on('all', () => this.scheduleRebuild());
  }

  private watchTargets(): string[] {
    const targets = [path.resolve(this.options.contentDir)];
    if (this.options.templateDir !== undefined) {
      targets.push(path.resolve(this.options.templateDir));
      return targets;
    }
    const defaultTemplates = path.resolve('templates');
    if (fs.existsSync(defaultTemplates) && fs.statSync(defaultTemplates).isDirectory()) {
      targets.push(defaultTemplates);
    }
    return targets;
  }

  private handleRequest(req: http.IncomingMessage, res: http.ServerResponse): void {
    let pathname: string;
    try {
      pathname = decodeURIComponent(new URL(req.url || '/', 'http://localhost').pathname);
    } catch {
      res.writeHead(400, { 'Content-Type': 'text/plain; charset=utf-8' });
      res.end('Bad Request');
      return;
    }
    if (pathname === '/') {
      pathname = '/index.html';
    }

    const outputDir = path.resolve(this.options.outputDir);
    let filePath = path.resolve(outputDir, `.${pathname}`);
    if (filePath !== outputDir && !filePath.startsWith(`${outputDir}${path.sep}`)) {
      res.writeHead(403, { 'Content-Type': 'text/plain; charset=utf-8' });
      res.end('Forbidden');
      return;
    }

    if (fs.existsSync(filePath) && fs.statSync(filePath).isDirectory()) {
      filePath = path.join(filePath, 'index.html');
    }

    if (!fs.existsSync(filePath) || !fs.statSync(filePath).isFile()) {
      res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
      res.end('Not Found');
      return;
    }

    const ext = path.extname(filePath).toLowerCase();
    const contentType = MIME_TYPES[ext] || 'application/octet-stream';
    const body = fs.readFileSync(filePath);

    if (contentType.startsWith('text/html')) {
      const html = injectLiveReload(body.toString('utf8'), buildWsUrl(req.headers.host));
      res.writeHead(200, {
        'Content-Type': contentType,
        'Content-Length': Buffer.byteLength(html),
      });
      res.end(html);
      return;
    }

    res.writeHead(200, { 'Content-Type': contentType, 'Content-Length': body.length });
    res.end(body);
  }

  private scheduleRebuild(): void {
    if (this.rebuildTimer !== null) {
      clearTimeout(this.rebuildTimer);
    }
    this.rebuildTimer = setTimeout(() => {
      this.rebuildTimer = null;
      this.rebuild();
    }, DEFAULT_REBUILD_DELAY_MS);
  }

  /**
   * Rebuild the site and notify connected browsers when it succeeds.
   * Returns true when the rebuild completed without errors.
   */
  rebuild(): boolean {
    try {
      buildSite({
        contentDir: this.options.contentDir,
        outputDir: this.options.outputDir,
        templateDir: this.options.templateDir,
      });
      this.reload();
      return true;
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      console.error(`Rebuild failed: ${message}`);
      return false;
    }
  }

  /**
   * Broadcast a `reload` message to every connected WebSocket client.
   */
  reload(): void {
    const message = JSON.stringify({ type: 'reload' });
    for (const client of this.clients) {
      if (client.readyState === WebSocket.OPEN) {
        client.send(message);
      }
    }
  }

  async close(): Promise<void> {
    if (this.rebuildTimer !== null) {
      clearTimeout(this.rebuildTimer);
      this.rebuildTimer = null;
    }
    await this.watcher.close();
    for (const client of this.clients) {
      client.terminate();
    }
    this.clients.clear();
    await new Promise<void>((resolve) => this.wss.close(() => resolve()));
    await new Promise<void>((resolve) => this.server.close(() => resolve()));
  }
}

/**
 * Start the dev server and wait until it is listening. Uses an ephemeral
 * port when `port` is 0.
 */
export function startDevServer(options: DevServerOptions): Promise<LiveReloadDevServer> {
  return new Promise((resolve, reject) => {
    const devServer = new LiveReloadDevServer(options);
    const onError = (error: Error) => {
      devServer.server.removeListener('listening', onListening);
      reject(error);
    };
    const onListening = () => {
      devServer.server.removeListener('error', onError);
      const address = devServer.server.address() as AddressInfo | null;
      if (address && typeof address === 'object') {
        devServer.port = address.port;
      }
      resolve(devServer);
    };
    devServer.server.once('error', onError);
    devServer.server.once('listening', onListening);
    devServer.server.listen(devServer.port);
  });
}

#!/usr/bin/env node
import { buildSite } from './generator';
import { startDevServer } from './dev-server';

const DEFAULT_CONTENT_DIR = './content';
const DEFAULT_OUTPUT_DIR = './dist';
const DEFAULT_TEMPLATE_DIR = './templates';
const DEFAULT_PORT = 3000;

export interface CliOptions {
  command: string;
  contentDir: string;
  outputDir: string;
  templateDir?: string;
  port: number;
}

export function parseArgs(argv: string[]): CliOptions {
  const opts: CliOptions = {
    command: '',
    contentDir: DEFAULT_CONTENT_DIR,
    outputDir: DEFAULT_OUTPUT_DIR,
    port: DEFAULT_PORT,
  };
  const args = argv.slice();
  if (args.length === 0) {
    return opts;
  }
  if (args.includes('--help') || args.includes('-h')) {
    opts.command = 'help';
    return opts;
  }
  opts.command = args[0] ?? '';
  for (let i = 1; i < args.length; i++) {
    const arg = args[i];
    if (arg === '--content') {
      opts.contentDir = args[i + 1] ?? DEFAULT_CONTENT_DIR;
      i += 1;
    } else if (arg === '--output') {
      opts.outputDir = args[i + 1] ?? DEFAULT_OUTPUT_DIR;
      i += 1;
    } else if (arg === '--templates') {
      opts.templateDir = args[i + 1] ?? DEFAULT_TEMPLATE_DIR;
      i += 1;
    } else if (arg === '--port') {
      const parsed = Number(args[i + 1]);
      opts.port = Number.isInteger(parsed) && parsed > 0 ? parsed : DEFAULT_PORT;
      i += 1;
    }
  }
  return opts;
}

export function printHelp(): void {
  console.log(
    [
      'Static Site Generator',
      '',
      'Usage:',
      '  npx ssg build [options]',
      '  npx ssg serve [options]',
      '',
      'Commands:',
      '  build    Build the site into the output directory',
      '  serve    Start a live-reload development server',
      '',
      'Options:',
      '  --content <dir>    Markdown content directory (default: ./content)',
      '  --output <dir>     Output directory (default: ./dist)',
      '  --templates <dir>  Template directory (default: ./templates)',
      '  --port <number>    Port for the dev server (default: 3000)',
      '  -h, --help         Show this help',
      '',
    ].join('\n')
  );
}

export function serveSite(opts: CliOptions): number {
  try {
    const pages = buildSite({
      contentDir: opts.contentDir,
      outputDir: opts.outputDir,
      templateDir: opts.templateDir,
    });
    console.log(`Built ${pages.length} page${pages.length === 1 ? '' : 's'} into ${opts.outputDir}`);
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    console.error(`Serve failed: ${message}`);
    return 1;
  }

  startDevServer({
    contentDir: opts.contentDir,
    outputDir: opts.outputDir,
    templateDir: opts.templateDir,
    port: opts.port,
  })
    .then((devServer) => {
      console.log(`Serving ${opts.outputDir} at http://localhost:${devServer.port}`);
      console.log('Watching content/ and templates/ for changes...');
    })
    .catch((error: unknown) => {
      const message = error instanceof Error ? error.message : String(error);
      console.error(`Serve failed: ${message}`);
      process.exitCode = 1;
    });

  return 0;
}

export function main(argv: string[]): number {
  const opts = parseArgs(argv);

  if (opts.command === 'help') {
    printHelp();
    return 0;
  }
  if (opts.command === 'serve') {
    return serveSite(opts);
  }
  if (opts.command !== 'build') {
    console.error(
      `Unknown command: "${opts.command}". Run "npx ssg build" or "npx ssg serve".`
    );
    return 1;
  }

  try {
    const pages = buildSite({
      contentDir: opts.contentDir,
      outputDir: opts.outputDir,
      templateDir: opts.templateDir,
    });
    console.log(`Built ${pages.length} page${pages.length === 1 ? '' : 's'} into ${opts.outputDir}`);
    return 0;
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    console.error(`Build failed: ${message}`);
    return 1;
  }
}

if (require.main === module) {
  process.exitCode = main(process.argv.slice(2));
}

import { spawn, spawnSync, ChildProcess } from 'child_process';
import fs from 'fs';
import http from 'http';
import os from 'os';
import path from 'path';
import WebSocket from 'ws';
import {
  LiveReloadDevServer,
  injectLiveReload,
  liveReloadScript,
  startDevServer,
} from '../src/dev-server';
import { parseArgs, printHelp } from '../src/cli';

const REPO_ROOT = path.resolve(__dirname, '..');
const CLI_JS = path.join(REPO_ROOT, 'dist', 'cli.js');

function makeTempDir(prefix: string): string {
  return fs.mkdtempSync(path.join(os.tmpdir(), prefix));
}

function writeContent(dir: string, files: Record<string, string>): void {
  fs.mkdirSync(dir, { recursive: true });
  for (const [name, content] of Object.entries(files)) {
    const filePath = path.join(dir, name);
    fs.mkdirSync(path.dirname(filePath), { recursive: true });
    fs.writeFileSync(filePath, content);
  }
}

function fetchText(url: string): Promise<string> {
  return new Promise((resolve, reject) => {
    http
      .get(url, (res) => {
        let body = '';
        res.setEncoding('utf8');
        res.on('data', (chunk) => {
          body += chunk;
        });
        res.on('end', () => resolve(body));
      })
      .on('error', reject);
  });
}

function fetchStatus(url: string): Promise<number> {
  return new Promise((resolve, reject) => {
    http
      .get(url, (res) => {
        res.resume();
        res.on('end', () => resolve(res.statusCode ?? 0));
      })
      .on('error', reject);
  });
}

function waitFor(predicate: () => boolean, timeoutMs = 8000): Promise<void> {
  const start = Date.now();
  return new Promise((resolve, reject) => {
    const check = () => {
      if (predicate()) {
        resolve();
        return;
      }
      if (Date.now() - start > timeoutMs) {
        reject(new Error('Timed out waiting for condition'));
        return;
      }
      setTimeout(check, 50);
    };
    check();
  });
}

async function waitForWsMessage(ws: WebSocket, timeoutMs = 8000): Promise<string> {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => {
      ws.removeAllListeners();
      reject(new Error('Timed out waiting for WebSocket message'));
    }, timeoutMs);
    ws.once('message', (data) => {
      clearTimeout(timer);
      resolve(data.toString());
    });
  });
}

function delay(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

async function buildFixture(): Promise<{ tmp: string; contentDir: string; outputDir: string }> {
  const tmp = makeTempDir('ssg-dev-');
  const contentDir = path.join(tmp, 'content');
  const outputDir = path.join(tmp, 'dist');
  writeContent(contentDir, {
    'home.md': '---\ntitle: Home\n---\n\n# Home page',
    'about.md': '---\ntitle: About\n---\n\n# About page',
  });
  return { tmp, contentDir, outputDir };
}

describe('parseArgs serve', () => {
  it('defaults the port to 3000', () => {
    const opts = parseArgs(['serve']);
    expect(opts.command).toBe('serve');
    expect(opts.port).toBe(3000);
  });

  it('parses --port', () => {
    const opts = parseArgs(['serve', '--port', '8080']);
    expect(opts.port).toBe(8080);
  });

  it('falls back to the default port for an invalid --port', () => {
    expect(parseArgs(['serve', '--port', 'abc']).port).toBe(3000);
    expect(parseArgs(['serve', '--port', '-1']).port).toBe(3000);
  });

  it('combines serve options with content, output and templates', () => {
    const opts = parseArgs(['serve', '--content', 'posts', '--output', 'public', '--port', '4000']);
    expect(opts.command).toBe('serve');
    expect(opts.contentDir).toBe('posts');
    expect(opts.outputDir).toBe('public');
    expect(opts.port).toBe(4000);
  });

  it('mentions serve and --port in help', () => {
    const spy = jest.spyOn(console, 'log').mockImplementation(() => undefined);
    printHelp();
    spy.mockRestore();
    const output = (spy.mock.calls[0] as string[]).join('\n');
    expect(output).toContain('npx ssg serve');
    expect(output).toContain('--port');
  });
});

describe('liveReloadScript / injectLiveReload', () => {
  it('creates a script that opens a WebSocket and reloads on message', () => {
    const script = liveReloadScript('ws://localhost:3000/__ssg_live_reload');
    expect(script).toContain('new WebSocket("ws://localhost:3000/__ssg_live_reload")');
    expect(script).toContain('window.location.reload()');
    expect(script).toContain('"reload"');
  });

  it('injects the script before the closing body tag', () => {
    const html = '<!DOCTYPE html><html><body><p>Hi</p></body></html>';
    const injected = injectLiveReload(html, 'ws://localhost:3000/__ssg_live_reload');
    expect(injected).toContain('<p>Hi</p>');
    expect(injected).toContain('ssg-live-reload');
    expect(injected.indexOf('ssg-live-reload')).toBeLessThan(injected.indexOf('</body>'));
  });

  it('appends the script when there is no body tag', () => {
    const injected = injectLiveReload('<html><p>Hi</p></html>', 'ws://localhost:3000/x');
    expect(injected).toContain('ssg-live-reload');
  });

  it('does not inject the script twice', () => {
    const once = injectLiveReload('<html><body></body></html>', 'ws://localhost:3000/x');
    const twice = injectLiveReload(once, 'ws://localhost:3000/x');
    expect(twice.match(/ssg-live-reload/g)).toHaveLength(1);
  });
});

describe('startDevServer serving', () => {
  it('serves built HTML from the output directory', async () => {
    const { contentDir, outputDir } = await buildFixture();
    const devServer = await startDevServer({ contentDir, outputDir, port: 0 });
    try {
      const base = `http://localhost:${devServer.port}`;
      const html = await fetchText(`${base}/about.html`);
      expect(html).toContain('<title>About</title>');
      expect(html).toContain('<h1>About</h1>');
    } finally {
      await devServer.close();
    }
  });

  it('serves index.html for the root path', async () => {
    const { contentDir, outputDir } = await buildFixture();
    const devServer = await startDevServer({ contentDir, outputDir, port: 0 });
    try {
      const html = await fetchText(`http://localhost:${devServer.port}/`);
      expect(html).toContain('<a href="about.html">About</a>');
      expect(html).toContain('<a href="home.html">Home</a>');
    } finally {
      await devServer.close();
    }
  });

  it('injects the live reload script into served HTML pages', async () => {
    const { contentDir, outputDir } = await buildFixture();
    const devServer = await startDevServer({ contentDir, outputDir, port: 0 });
    try {
      const html = await fetchText(`http://localhost:${devServer.port}/home.html`);
      expect(html).toContain('ssg-live-reload');
      expect(html).toContain(`ws://localhost:${devServer.port}/__ssg_live_reload`);
    } finally {
      await devServer.close();
    }
  });

  it('returns 404 for missing files', async () => {
    const { contentDir, outputDir } = await buildFixture();
    const devServer = await startDevServer({ contentDir, outputDir, port: 0 });
    try {
      const status = await fetchStatus(`http://localhost:${devServer.port}/nope.html`);
      expect(status).toBe(404);
    } finally {
      await devServer.close();
    }
  });

  it('does not inject the script into non-HTML files', async () => {
    const { contentDir, outputDir } = await buildFixture();
    fs.writeFileSync(path.join(outputDir, 'styles.css'), 'body { color: red; }');
    const devServer = await startDevServer({ contentDir, outputDir, port: 0 });
    try {
      const css = await fetchText(`http://localhost:${devServer.port}/styles.css`);
      expect(css).toContain('body { color: red; }');
      expect(css).not.toContain('ssg-live-reload');
    } finally {
      await devServer.close();
    }
  });
});

describe('live reload rebuild', () => {
  it('rebuilds and broadcasts reload when content changes', async () => {
    const { contentDir, outputDir } = await buildFixture();
    const devServer = await startDevServer({ contentDir, outputDir, port: 0 });
    try {
      const ws = new WebSocket(
        `ws://localhost:${devServer.port}/__ssg_live_reload`,
        { headers: { Origin: `http://localhost:${devServer.port}` } }
      );
      await new Promise<void>((resolve, reject) => {
        ws.once('open', resolve);
        ws.once('error', reject);
      });

      fs.writeFileSync(path.join(contentDir, 'home.md'), '---\ntitle: Home Updated\n---\n\n# Home page v2');
      const message = await waitForWsMessage(ws);
      expect(JSON.parse(message)).toEqual({ type: 'reload' });

      await waitFor(() =>
        fs.readFileSync(path.join(outputDir, 'home.html'), 'utf8').includes('Home Updated')
      );
      ws.close();
    } finally {
      await devServer.close();
    }
  });

  it('serves rebuilt content after a change', async () => {
    const { contentDir, outputDir } = await buildFixture();
    const devServer = await startDevServer({ contentDir, outputDir, port: 0 });
    try {
      fs.writeFileSync(path.join(contentDir, 'about.md'), '---\ntitle: About v2\n---\n\n# About page v2');
      await waitFor(() =>
        fs.readFileSync(path.join(outputDir, 'about.html'), 'utf8').includes('About v2')
      );
      const html = await fetchText(`http://localhost:${devServer.port}/about.html`);
      expect(html).toContain('About v2');
    } finally {
      await devServer.close();
    }
  });

  it('keeps serving when a rebuild fails and recovers on the next change', async () => {
    const { contentDir, outputDir } = await buildFixture();
    const devServer = await startDevServer({ contentDir, outputDir, port: 0 });
    const errorSpy = jest.spyOn(console, 'error').mockImplementation(() => undefined);
    try {
      fs.writeFileSync(path.join(contentDir, 'broken.md'), '---\ntitle: [unclosed\n---\n\n# Broken');
      await delay(300);

      const html = await fetchText(`http://localhost:${devServer.port}/home.html`);
      expect(html).toContain('Home page');

      fs.writeFileSync(path.join(contentDir, 'fixed.md'), '# Fixed\n');
      await waitFor(() => fs.existsSync(path.join(outputDir, 'fixed.html')));
      const fixed = await fetchText(`http://localhost:${devServer.port}/fixed.html`);
      expect(fixed).toContain('Fixed');
    } finally {
      errorSpy.mockRestore();
      await devServer.close();
    }
  });
});

describe('serve CLI binary', () => {
  function ensureBuilt(): void {
    if (!fs.existsSync(CLI_JS)) {
      const result = spawnSync('npx', ['tsc'], { cwd: REPO_ROOT, encoding: 'utf8' });
      if (result.status !== 0) {
        throw new Error(`Failed to build TypeScript: ${result.stderr}`);
      }
    }
  }

  beforeAll(() => {
    ensureBuilt();
  });

  it('starts a live-reload server and serves the site', async () => {
    const { contentDir, outputDir } = await buildFixture();

    const child: ChildProcess = spawn(
      process.execPath,
      [CLI_JS, 'serve', '--content', contentDir, '--output', outputDir, '--port', '0'],
      { cwd: REPO_ROOT, encoding: 'utf8' }
    );
    let stdout = '';
    let stderr = '';
    child.stdout?.on('data', (chunk: string) => {
      stdout += chunk;
    });
    child.stderr?.on('data', (chunk: string) => {
      stderr += chunk;
    });

    try {
      await waitFor(() => stdout.includes('Serving') && /localhost:\d+/.test(stdout));
      expect(stderr).toBe('');
      const port = Number(stdout.match(/localhost:(\d+)/)?.[1]);
      expect(Number.isInteger(port) && port > 0).toBe(true);

      const html = await fetchText(`http://localhost:${port}/home.html`);
      expect(html).toContain('Home page');
      expect(html).toContain('ssg-live-reload');
    } finally {
      child.kill('SIGTERM');
      await delay(300);
    }
  });

  it('fails with a non-zero exit code for a missing content directory', () => {
    const tmp = makeTempDir('ssg-serve-missing-');
    const result = spawnSync(
      process.execPath,
      [CLI_JS, 'serve', '--content', path.join(tmp, 'nope')],
      { cwd: REPO_ROOT, encoding: 'utf8' }
    );
    expect(result.status).not.toBe(0);
    expect(result.stderr).toContain('Serve failed');
  });
});

